DASHBOARD_HTML = r'''<!doctype html>
<html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Veloikos Trading</title>
<style>
:root{--bg:#080b0d;--card:#101619;--card2:#131c20;--line:#26343a;--ink:#f2f5f4;--muted:#98a8ad;--green:#23c983;--red:#f26e78;--gold:#d9b86a;--blue:#71b8ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px Inter,system-ui,-apple-system,sans-serif}header{height:58px;display:flex;align-items:center;justify-content:space-between;padding:0 18px;border-bottom:1px solid var(--line);position:sticky;top:0;background:#090d0f;z-index:5}.brand{font:700 22px Georgia,serif}.brand small{color:var(--gold);font:700 9px Inter,sans-serif;letter-spacing:2px;margin-left:6px}.live{font-size:10px;color:var(--green);border:1px solid #265b43;padding:6px 8px;border-radius:99px}.app{max-width:1500px;margin:auto;padding:16px}.overview{display:grid;grid-template-columns:repeat(5,1fr);border:1px solid var(--line);background:var(--card)}.metric{padding:13px 14px;border-right:1px solid var(--line)}.metric:last-child{border-right:0}.label{font-size:10px;letter-spacing:1.25px;text-transform:uppercase;color:var(--muted)}.metric b{display:block;font-size:19px;margin-top:6px}.green{color:var(--green)}.red{color:var(--red)}.tabs{display:none}.workspace{display:grid;grid-template-columns:190px minmax(0,1fr) 300px;gap:14px;margin-top:14px}.card{background:var(--card);border:1px solid var(--line)}.card h2{font-size:13px;margin:0;padding:12px 14px;border-bottom:1px solid var(--line)}.watch{display:block;width:100%;padding:12px 14px;color:var(--ink);background:none;border:0;border-bottom:1px solid #1f2a2e;text-align:left;cursor:pointer}.watch:hover,.watch.active{background:#16241f;border-left:3px solid var(--gold)}.watch b{display:block}.watch span{font-size:11px;color:var(--muted)}.market-head{display:flex;justify-content:space-between;align-items:end;padding:12px 2px}.symbol{font-size:32px;font-weight:800}.quote{display:grid;grid-template-columns:repeat(4,minmax(70px,1fr));gap:16px;text-align:right}.quote b{display:block;margin-top:4px;font-size:16px}.chart{height:390px;position:relative}.chart-top{padding:11px 14px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;font-size:12px}.chart-note{color:var(--muted)}svg{width:100%;height:calc(100% - 40px);display:block}.rows{padding:0 14px}.row{display:grid;grid-template-columns:1fr auto;gap:10px;align-items:center;padding:11px 0;border-bottom:1px solid #202a2f}.row:last-child{border-bottom:0}.sub{font-size:11px;color:var(--muted);margin-top:3px}.position{padding:14px}.position h3{margin:0;font-size:18px}.pair{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid #202a2f}.pair:last-child{border:0}.timeline{padding:0 14px}.event{display:grid;grid-template-columns:8px 1fr auto;gap:9px;padding:11px 0;border-bottom:1px solid #202a2f}.dot{width:7px;height:7px;background:var(--gold);border-radius:50%;margin-top:5px}.time{font-size:11px;color:var(--muted);white-space:nowrap}.footer-note{padding:12px 14px;color:var(--muted);font-size:11px;line-height:1.4}.research{margin-top:14px}.research-head{display:flex;justify-content:space-between;align-items:center;padding:12px 14px;border-bottom:1px solid var(--line)}.research-grid{display:grid;grid-template-columns:repeat(5,1fr)}.candidate{padding:14px;border-right:1px solid var(--line);min-height:96px}.candidate:last-child{border:0}.candidate b{font-size:17px}.rank{color:var(--gold);font-size:11px}.status{display:inline-block;margin-top:8px;font-size:10px;color:var(--blue);border:1px solid #31536b;border-radius:99px;padding:3px 6px}.desktop-only{display:block}@media(max-width:850px){header{padding:0 12px}.app{padding:0 10px 18px}.overview{grid-template-columns:repeat(2,1fr);margin:10px 0}.metric{border-bottom:1px solid var(--line)}.metric:nth-child(2n){border-right:0}.metric:last-child{grid-column:span 2;border-bottom:0}.tabs{display:flex;gap:6px;padding:9px 0}.tab{flex:1;padding:9px;background:#101619;color:var(--muted);border:1px solid var(--line);border-radius:6px;font-size:12px}.tab.active{color:var(--ink);border-color:var(--gold);background:#19211f}.workspace{display:block;margin-top:0}.pane{display:none}.pane.active{display:block}.watchlist{display:flex;overflow-x:auto;gap:7px;padding:10px;border-bottom:1px solid var(--line)}.watch{min-width:86px;border:1px solid var(--line);border-radius:6px;padding:9px}.chart{height:310px}.quote{gap:10px}.quote .label{font-size:9px}.quote b{font-size:13px}.market-head{padding:9px 2px}.symbol{font-size:27px}.desktop-only{display:none}.card{margin-bottom:10px}.history{max-height:300px;overflow:auto}.research-grid{grid-template-columns:repeat(2,1fr)}.candidate:nth-child(2n){border-right:0}.candidate:last-child{border-bottom:0}}@media(min-width:851px){.watchlist{display:block}}
</style></head><body>
<header><div class="brand">Veloikos <small>TRADING</small></div><div id="liveBadge" class="live">LIVE EXECUTION ACTIVE</div></header>
<div class="app"><section class="overview"><div class="metric"><span class="label">Equity</span><b id="equity">$--</b></div><div class="metric"><span class="label">Cash</span><b id="cash">$--</b></div><div class="metric"><span class="label">Buying power</span><b id="power">$--</b></div><div class="metric"><span class="label">Open positions</span><b id="count">0</b></div><div class="metric"><span class="label">Market</span><b id="market">--</b></div></section>
<nav class="tabs"><button class="tab active" data-pane="marketPane">Market</button><button class="tab" data-pane="portfolioPane">Portfolio</button><button class="tab" data-pane="activityPane">Activity</button></nav>
<section class="workspace"><aside id="marketPane" class="pane active card"><h2 class="desktop-only">Watchlist</h2><div id="watch" class="watchlist"></div></aside>
<main id="chartPane" class="pane active"><section class="market-head"><div><div class="label">Selected instrument</div><div id="symbol" class="symbol">SPY</div><div id="feed" class="sub green">Loading broker quote</div></div><div class="quote"><div><span class="label">Last</span><b id="last">--</b></div><div><span class="label">Bid</span><b id="bid">--</b></div><div><span class="label">Ask</span><b id="ask">--</b></div><div><span class="label">Spread</span><b id="spread">--</b></div></div></section><section class="card chart"><div class="chart-top"><b id="chartName">SPY daily candles</b><span id="chartNote" class="chart-note">Loading market data</span></div><svg id="chart" viewBox="0 0 1000 330" preserveAspectRatio="none"></svg></section></main>
<aside id="portfolioPane" class="pane card"><h2>Live position</h2><div id="position" class="position">Loading broker position</div><h2>Recent trades</h2><div id="trades" class="rows history">Loading ledger</div></aside>
<aside id="activityPane" class="pane card"><h2>Execution activity</h2><div id="activity" class="timeline">Loading worker events</div><div class="footer-note">The worker only sends an order after its signal, quote quality, allocation, and protection checks pass.</div></aside></section><section class="card research"><div class="research-head"><div><span class="label">Expanded research coverage</span><h2>Liquid-market candidates</h2></div><span id="researchMeta" class="status">Loading scan</span></div><div id="researchRows" class="research-grid"><div class="candidate">Loading research candidates</div></div><div class="footer-note">Research candidates are not trade signals. A separate validation and paper lifecycle is required before any live-universe change.</div></section></div>
<script>
const syms=['SPY','QQQ','IWM','NVDA','AAPL','MSFT','GLD','TLT'];let selected='SPY';const q=s=>document.querySelector(s),money=n=>Number(n||0).toLocaleString('en-US',{style:'currency',currency:'USD'}),esc=s=>String(s??'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
function drawWatch(){q('#watch').innerHTML=syms.map(s=>'<button class="watch '+(s===selected?'active':'')+'" data-s="'+s+'"><b>'+s+'</b><span>'+ (s===selected?'Selected':'View chart')+'</span></button>').join('');document.querySelectorAll('.watch').forEach(x=>x.onclick=()=>{selected=x.dataset.s;drawWatch();loadMarket()})}
function candles(b){let v=q('#chart');if(!b||!b.length){v.innerHTML='<text x="500" y="165" text-anchor="middle" fill="#98a8ad" font-size="15">Market data unavailable</text>';return}let w=1000,h=330,p=24,lo=Math.min(...b.map(x=>+x.low)),hi=Math.max(...b.map(x=>+x.high)),span=Math.max(hi-lo,.01),y=n=>h-p-(n-lo)/span*(h-2*p),step=(w-2*p)/b.length,bw=Math.max(3,step*.58),s='';for(let i=0;i<5;i++){let yy=p+i*(h-2*p)/4;s+='<line x1="'+p+'" x2="'+(w-p)+'" y1="'+yy+'" y2="'+yy+'" stroke="#26343a"/>'}b.forEach((x,i)=>{let c=+x.close>=+x.open?'#23c983':'#f26e78',cx=p+i*step+step/2,t=y(Math.max(+x.open,+x.close)),bh=Math.max(2,Math.abs(y(+x.open)-y(+x.close)));s+='<line x1="'+cx+'" x2="'+cx+'" y1="'+y(+x.high)+'" y2="'+y(+x.low)+'" stroke="'+c+'"/><rect x="'+(cx-bw/2)+'" y="'+t+'" width="'+bw+'" height="'+bh+'" fill="'+c+'"/>'});s+='<text x="'+p+'" y="15" fill="#98a8ad" font-size="11">'+hi.toFixed(2)+'</text><text x="'+p+'" y="'+(h-8)+'" fill="#98a8ad" font-size="11">'+lo.toFixed(2)+'</text>';v.innerHTML=s}
async function loadMarket(){q('#symbol').textContent=selected;q('#chartName').textContent=selected+' daily candles';try{let d=await fetch('/terminal/market?symbol='+selected).then(r=>r.ok?r.json():Promise.reject()),z=d.quote||{},bid=+z.bid||0,ask=+z.ask||0;q('#last').textContent=z.last?money(z.last):'--';q('#bid').textContent=bid?money(bid):'--';q('#ask').textContent=ask?money(ask):'--';q('#spread').textContent=bid&&ask?money(ask-bid):'--';q('#feed').textContent=z.last?'Broker quote loaded':'No current quote';q('#chartNote').textContent=(d.bars||[]).length+' daily bars';candles(d.bars||[])}catch(e){q('#feed').textContent='Market data temporarily unavailable';q('#chartNote').textContent='Retrying automatically';candles([])}}
function eventTitle(e){return String(e.type||'activity').replace(/^alpaca_live_worker_/,'Worker: ').replace(/^alpaca_live_/,'Live: ').replaceAll('_',' ')}function eventDetail(e){let p=e.payload||{};return p.reasons?.join(', ')||p.strategy||p.reason||'Execution audit record'}
async function loadAccount(){try{let[d,t,a]=await Promise.all([fetch('/brokers/alpaca/live-portfolio').then(r=>r.json()),fetch('/live/trades').then(r=>r.json()),fetch('/live/activity?limit=10').then(r=>r.json())]),b=d.balances||{},p=d.positions||[],o=d.active_orders||[];q('#equity').textContent=money(b.equity);q('#cash').textContent=money(b.cash);q('#power').textContent=money(b.buying_power);q('#count').textContent=p.length;q('#market').textContent=d.market_clock?.is_open?'Open':'Closed';let pos=p[0],stop=o.find(x=>x.symbol===pos?.symbol&&x.type==='stop');q('#position').innerHTML=pos?'<h3>'+esc(pos.symbol)+' <span class="'+(+pos.unrealized_pl>=0?'green':'red')+'">'+money(pos.unrealized_pl)+'</span></h3><div class="sub">'+esc(pos.qty)+' shares | entry '+money(pos.avg_entry_price)+'</div><div class="pair"><span>Market value</span><b>'+money(pos.market_value)+'</b></div><div class="pair"><span>Protective stop</span><b class="red">'+(stop?money(stop.stop_price):'VERIFYING')+'</b></div><div class="pair"><span>Stop status</span><b class="'+(stop?'green':'red')+'">'+(stop?esc(stop.status):'No active stop')+'</b></div>':'<h3>No live position</h3><div class="sub">The worker is scanning for an eligible setup.</div>';q('#trades').innerHTML=(t.trades||[]).slice(0,6).map(x=>'<div class="row"><div><b>'+esc(x.symbol)+' '+esc(x.status)+'</b><div class="sub">'+(x.exit_reason?esc(x.exit_reason):'Entry '+money(x.entry_price))+'</div></div><b class="'+(+x.pnl>=0?'green':'red')+'">'+(x.pnl==null?'Open':money(x.pnl))+'</b></div>').join('')||'<div class="row">No recorded trades</div>';q('#activity').innerHTML=(a.events||[]).slice(0,8).map(e=>'<div class="event"><i class="dot"></i><div><b>'+esc(eventTitle(e))+'</b><div class="sub">'+esc(eventDetail(e))+'</div></div><span class="time">'+new Date(String(e.timestamp).endsWith('Z')?e.timestamp:e.timestamp+'Z').toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})+'</span></div>').join('')||'<div class="event">No worker events</div>'}catch(e){q('#activity').innerHTML='<div class="event">Broker snapshot unavailable; retrying.</div>'}}
async function loadResearch(){try{let d=await fetch('/research/expanded-equity-scan').then(r=>r.ok?r.json():Promise.reject()),s=d.scan||{},rows=(s.ranked||[]).slice(0,5);q('#researchMeta').textContent=(s.symbols||[]).length+' symbols · research only';q('#researchRows').innerHTML=rows.map((x,i)=>'<div class="candidate"><div class="rank">#'+(i+1)+' · score '+Number(x.score||0).toFixed(3)+'</div><b>'+esc(x.symbol)+'</b><div class="sub">'+esc(x.asset_class||'us equity')+'</div><span class="status">'+esc(x.reason||'research only')+'</span></div>').join('')||'<div class="candidate">No scan recorded yet</div>'}catch(e){q('#researchMeta').textContent='Retrying scan data';q('#researchRows').innerHTML='<div class="candidate">Research scan unavailable</div>'}}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');let id=b.dataset.pane;document.querySelectorAll('.pane').forEach(x=>x.classList.remove('active'));q('#'+id).classList.add('active');if(id==='marketPane')q('#chartPane').classList.add('active')});drawWatch();loadMarket();loadAccount();loadResearch();setInterval(loadMarket,20000);setInterval(loadAccount,10000);setInterval(loadResearch,60000);
</script></body></html>'''
